const obs = phi.observe({ maxElements: 400});
const main = phi.query("main a, .content a, article a", { limit: 300 });
const all = phi.query("a", { limit: 400 });
return {
  url: obs.url,
  title: obs.title,
  nodes: obs.nodes.map(n => n.role + " | " + (n.name||"").slice(0,80)).slice(0,120),
  mainCount: main.total,
  mainItems: main.items.map(a => (a.text||"").slice(0,90) + " || " + (a.href||"")),
  allCount: all.total
};

const all = phi.query("main a", { limit: 400 });
const items = all.items.map(a => ({ t: (a.text||"").trim(), h: a.href }));
const stations = items.filter(x => /mta\.info\/document\//.test(x.h || "") && x.t);
const other = items.filter(x => !(/mta\.info\/document\//.test(x.h || "") && x.t));
phi.keep("brooklyn_maps", { total: all.total, stationCount: stations.length, stations });
return { total: all.total, stationCount: stations.length, first: stations.slice(0,3), last: stations.slice(-3), other: other.map(o=>o.t+" || "+o.h).slice(0,40), otherCount: other.length };

const obs = phi.observe({ maxElements: 60 });
const all = phi.query("a", { limit: 400 });
const items = all.items.map(a => ({ t: (a.text||"").trim(), h: a.href || "" }));
const stations = items.filter(x => /\/document\//.test(x.h) && x.t);
phi.keep("brooklyn_maps", { total: all.total, stationCount: stations.length, stations });
return { url: obs.url, title: obs.title, allTotal: all.total, stationCount: stations.length, first: stations.slice(0,3), last: stations.slice(-3) };

const maps = phi.recall("brooklyn_maps");
const names = maps.stations.map(s => s.t);
