const heads = phi.query("h1, h2, h3", { limit: 40 }).items.map(h => h.text.trim()).filter(Boolean);
const txt = phi.text();
const idx = txt.indexOf("Neighborhood maps");
const snippet = idx >= 0 ? txt.slice(Math.max(0, idx - 200), idx + 900) : txt.slice(0, 900);
// any filter/search control on page?
const inputs = phi.query("input, select", { limit: 20 }).items.map(i => (i.type || i.tag || "") + " | " + (i.name || "") + " | " + (i.placeholder || ""));
phi.keep("brooklyn_maps", { pageTitle: "Brooklyn neighborhood maps", url: "https://www.mta.info/maps/neighborhood-maps/brooklyn", count: names.length, names, first: names.slice(0,3), last: names.slice(-3) });
return { count: names.length, heads: heads.slice(0, 20), snippet: snippet.slice(0, 700), inputs: inputs.slice(0, 10) };

const check = phi.js(() => {
  const as = Array.from(document.querySelectorAll('a[href*="/document/"]'));
  const vis = as.filter(a => a.offsetParent !== null && a.textContent.trim());
  const texts = vis.map(a => a.textContent.trim());
  const h1 = document.querySelector('h1')?.textContent.trim();
  // pagination / pager?
  const pager = Array.from(document.querySelectorAll('.pager, .pagination, nav[aria-label*="agion"], a[rel="next"]')).map(e => e.textContent.trim().slice(0,60));
  const mainEl = document.querySelector('main') || document.body;
  const inMain = vis.filter(a => mainEl.contains(a)).length;
  return { h1, docLinks: as.length, visibleWithText: vis.length, inMain, pagerCount: pager.length, pager: pager.slice(0,5), first5: texts.slice(0,5), last5: texts.slice(-5) };
});
